import csv
import re

_RECORD_SPLIT = re.compile(r'\r\n|\r|\n')


def parse_csv(text: str) -> list[list[str]]:
    if text.startswith('\ufeff'):
        text = text[1:]
    rows: list[list[str]] = []
    for line in _RECORD_SPLIT.split(text):
        if not line.strip():
            continue
        stripped = line.lstrip()
        if stripped.startswith('#'):
            continue
        for row in csv.reader([line]):
            if any(field.strip() for field in row):
                rows.append(row)
    return rows
